function eraseOverlapIntervals(intervals: number[][]): number {
  const sorted = [...intervals].sort((a, b) => a[1] - b[1])
  let end = -Infinity
  let kept = 0
  for (const [s, e] of sorted) {
    if (s >= end) {
      kept++
      end = e
    }
  }
  return intervals.length - kept
}
